test('choice and gifts return typed relationships and milestone once', () {
  final map = validWorld();
  final initial = _initialFor(map).copyWith(
    inventory: InventoryState(
      itemCounts: {testMoonflowerResource.mapValue: 2},
    ),
    relationships: {
      RuntimeGameState.npc01Id: NpcRelationshipState(
        npcId: RuntimeGameState.npc01Id,
        learnedFactIds: const {'npc-01-moonflower-preference'},
      ),
    },
  );
  final controller = _controller(
    map: map,
    catalog: catalog,
    loadedState: initial,
  );
  addTearDown(controller.dispose);

  final initialDialogue = controller.resolveDialogueForNpc(
    WorldMapAuthoringRegistry.npc01.mapValue,
  )!;
  final choice = controller.selectDialogueChoice(
    initialDialogue,
    Npc01DialogueIds.npc01HelpfulChoiceId,
  )!;

  expect(choice.previousRelationship.affinity, 0);
  expect(choice.nextRelationship.affinity, 1);
  expect(choice.milestoneDialogue, isNull);

  final followUp = controller.resolveDialogueForNpc(
    WorldMapAuthoringRegistry.npc01.mapValue,
  )!;
  final firstGift = controller.giveGift(followUp)!;
  final secondGift = controller.giveGift(followUp)!;
  final milestone = catalog
      .findById(RuntimeGameState.npc01Id)!
      .runtime
      .relationship
      .levelOneMilestone!;

  expect(firstGift.previousRelationship.affinity, 1);
  expect(firstGift.nextRelationship.affinity, 2);
  expect(firstGift.milestoneDialogue, isNull);
  expect(secondGift.previousRelationship.affinity, 2);
  expect(secondGift.nextRelationship.affinity, 3);
  expect(secondGift.milestoneDialogue?.id, milestone.dialogueNodeId);
  expect(secondGift.nextRelationship.flags, contains(milestone.seenFlagId));
  expect(controller.giveGift(followUp), isNull);
  expect(
    controller
        .resolveDialogueForNpc(WorldMapAuthoringRegistry.npc01.mapValue)
        ?.id,
    Npc01DialogueIds.npc01FollowUpNodeId,
  );
});

test(
  'gift selector changes only at dialogue and final availability edges',
  () {
    final map = validWorld();
    final initial = _initialFor(map).copyWith(
      inventory: InventoryState(
        itemCounts: {testMoonflowerResource.mapValue: 2},
      ),
      relationships: {
        RuntimeGameState.npc01Id: NpcRelationshipState(
          npcId: RuntimeGameState.npc01Id,
          learnedFactIds: const {'npc-01-moonflower-preference'},
          flags: const {Npc01DialogueIds.firstConversationCompleteFlag},
        ),
      },
    );
    final controller = _controller(
      map: map,
      catalog: catalog,
      loadedState: initial,
    );
    addTearDown(controller.dispose);
    final dialogue = controller.resolveDialogueForNpc(
      WorldMapAuthoringRegistry.npc01.mapValue,
    )!;
    var giftNotifications = 0;
    controller.canGiveGiftListenable.addListener(() => giftNotifications++);

    controller.setActiveDialogue(dialogue);
    expect(controller.canGiveGift, isTrue);
    expect(giftNotifications, 1);

    controller.giveGift(dialogue);
    expect(controller.canGiveGift, isTrue);
    expect(giftNotifications, 1);

    controller.giveGift(dialogue);
    expect(controller.canGiveGift, isFalse);
    expect(giftNotifications, 2);

    controller.setActiveDialogue(null);
    expect(giftNotifications, 2);
  },
);
